<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{WorkflowRepository,SettingsRepository,AcademicRepository,SupportRepository,StudentRepository};use App\Support\Flash;
final class ExamsController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function w():WorkflowRepository{return new WorkflowRepository($this->app->database());}private function data():array{$i=$this->i();return['exams'=>$this->w()->exams($i),'classes'=>(new AcademicRepository($this->app->database()))->classes($i),'subjects'=>(new SupportRepository($this->app->database()))->subjects($i)];}
public function create(Request$r):Response{return$this->renderPage('exam-create',$this->data());}public function store(Request$r):Response{try{$this->w()->createExam($this->i(),(string)$r->input('examname'),(string)$r->input('startdate'),(string)$r->input('enddate'),(int)user()['id']);}catch(\Throwable$e){return Response::html(e($e->getMessage()),422);}Flash::add('success','Exam created.');return Response::redirect(url('/admin/exams/create'));}public function delete(Request$r):Response{if(!$this->w()->deleteExam($this->i(),(int)$r->route('id')))return Response::html('Exam not found',404);return Response::redirect(url('/admin/exams/create'));}
public function setup(Request$r):Response{return$this->renderPage('exam-setup',$this->data()+['setups'=>$this->w()->examSetups($this->i())]);}public function saveSetup(Request$r):Response{try{$this->w()->setupExam($this->i(),(int)$r->input('exam'),(int)$r->input('class'),(int)$r->input('subject'),(float)$r->input('total_marks'));}catch(\DomainException$e){return Response::html(e($e->getMessage()),422);}return Response::redirect(url('/admin/exams/setup'));}
public function marks(Request$r):Response{$setup=(int)$r->query('setup',0);return$this->renderPage('exam-marks',$this->data()+['setups'=>$this->w()->examSetups($this->i()),'selectedSetup'=>$setup,'students'=>$setup?$this->w()->examMarkSheet($this->i(),$setup):[]]);}public function saveMarks(Request$r):Response{try{$this->w()->saveExamMarks($this->i(),(int)$r->input('exam_subject_id'),(array)$r->input('marks',[]),(int)user()['id'],(array)$r->input('absent',[]));}catch(\DomainException$e){return Response::html(e($e->getMessage()),422);}return Response::redirect(url('/admin/exams/marks?setup='.$r->input('exam_subject_id')));}
public function results(Request$r):Response{$exam=(int)$r->query('exam',0);$class=(int)$r->query('class',0);$student=(int)$r->query('student',0);return$this->renderPage('exam-results',$this->data()+['students'=>(new StudentRepository($this->app->database()))->paginate($this->i(),'',null,100),'selectedExam'=>$exam,'selectedClass'=>$class,'selectedStudent'=>$student,'result'=>$student&&$exam?$this->w()->studentResult($this->i(),$exam,$student):null,'rows'=>$class&&$exam?$this->w()->classResults($this->i(),$exam,$class):[]]);}
public function status(Request$r):Response{try{if(!$this->w()->setExamStatus($this->i(),(int)$r->route('id'),(string)$r->input('status')))return Response::html('Exam not found',404);Flash::add('success','Exam workflow status updated.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/exams/create'));}
}
